package app.kinexo;
import android.app.*; import android.os.*; import android.graphics.Color; import android.view.*; import android.widget.*; import android.net.Uri; import org.json.*; import java.net.*; import java.io.*;
public class MainActivity extends Activity {
 LinearLayout root,results; EditText query; VideoView video; int generation=0;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(25,30,40));t.setPadding(0,dp(10),0,dp(10));return t;}
 public void onCreate(Bundle b){super.onCreate(b);home();}
 void home(){generation++; video=null; root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(32),dp(24),dp(16));root.setBackgroundColor(Color.WHITE);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(24),dp(20)+i.getSystemWindowInsetTop(),dp(24),dp(16)+i.getSystemWindowInsetBottom());return i;});root.addView(label("KINEXO",36));root.addView(label("Найди. Нажми. Смотри.",16));query=new EditText(this);query.setSingleLine(true);query.setHint("Название фильма");query.setImeOptions(3);root.addView(query);Button b=new Button(this);b.setText("Найти");root.addView(b);b.setOnClickListener(v->search());query.setOnEditorActionListener((v,a,e)->{search();return true;});ScrollView sc=new ScrollView(this);results=new LinearLayout(this);results.setOrientation(1);sc.addView(results);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));results.addView(label("Тестовый источник: Internet Archive. Попробуйте Night of the Living Dead или Big Buck Bunny.",15));}
 JSONObject get(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>8000000)throw new IOException("Response too large");}return new JSONObject(out.toString("UTF-8"));}finally{c.disconnect();}}
 String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 void search(){String q=query.getText().toString().trim();if(q.isEmpty())return;int token=++generation;results.removeAllViews();results.addView(label("Поиск…",16));new Thread(()->{try{String safe=q.replaceAll("[^\\p{L}\\p{N} ]"," ");JSONObject j=get("https://archive.org/advancedsearch.php?q="+enc("title:("+safe+") AND mediatype:movies AND (licenseurl:*creativecommons.org* OR collection:opensource_movies)")+"&fl[]=identifier&fl[]=title&rows=25&output=json");JSONArray a=j.getJSONObject("response").getJSONArray("docs");runOnUiThread(()->{if(token!=generation)return;results.removeAllViews();if(a.length()==0)results.addView(label("Ничего не найдено",18));for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m==null)continue;String id=m.optString("identifier"),title=m.optString("title",id);Button row=new Button(this);row.setAllCaps(false);row.setText("▶  "+title);results.addView(row);row.setOnClickListener(v->resolve(id,title));}});}catch(Exception e){runOnUiThread(()->{if(token==generation){results.removeAllViews();results.addView(label("Ошибка сети. Повторите поиск.",16));}});}}).start();}
 void resolve(String id,String title){int token=++generation;results.removeAllViews();results.addView(label("Подготовка видео…",16));new Thread(()->{try{JSONObject j=get("https://archive.org/metadata/"+enc(id));JSONArray a=j.getJSONArray("files");String path=null;for(int i=0;i<a.length();i++){String n=a.getJSONObject(i).optString("name");if(n.toLowerCase(java.util.Locale.ROOT).endsWith(".mp4")){path=n;break;}}if(path==null)throw new IOException();String url="https://archive.org/download/"+Uri.encode(id)+"/"+Uri.encode(path,"/");runOnUiThread(()->{if(token==generation)play(title,url);});}catch(Exception e){runOnUiThread(()->{if(token==generation){results.removeAllViews();results.addView(label("Видео недоступно. Повторите поиск.",16));}});}}).start();}
 void play(String title,String url){root.removeAllViews();Button back=new Button(this);back.setText("Назад к поиску");root.addView(back);back.setOnClickListener(v->{video.stopPlayback();home();});root.addView(label(title,22));video=new VideoView(this);root.addView(video,new LinearLayout.LayoutParams(-1,0,1));MediaController c=new MediaController(this);c.setAnchorView(video);video.setMediaController(c);video.setOnErrorListener((m,w,e)->{Toast.makeText(this,"Не удалось воспроизвести видео",Toast.LENGTH_LONG).show();return true;});video.setVideoURI(Uri.parse(url));video.setOnPreparedListener(m->video.start());}
 @Override public void onBackPressed(){if(video!=null){video.stopPlayback();home();}else super.onBackPressed();}
 @Override protected void onStop(){super.onStop();if(video!=null)video.pause();}
}
